import{_ as t,o as i,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Making the Right Hardware Choices | Ceph Days London 2024","description":"","frontmatter":{"title":"Making the Right Hardware Choices | Ceph Days London 2024","date":"2024-08-23T00:00:00.000Z","updated":"2024-08-24T00:00:00.000Z","tags":["Ceph","存储系统","硬件选型","性能优化","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Making_the_Right_Hardware_Choices_Ceph_Days_London_2024.md","filePath":"posts/2024/Making_the_Right_Hardware_Choices_Ceph_Days_London_2024.md","lastUpdated":1780459816000}'),p={name:"posts/2024/Making_the_Right_Hardware_Choices_Ceph_Days_London_2024.md"};function s(n,o,r,_,a,g){return i(),e("div",null,[...o[0]||(o[0]=[l("<p>会议纪要</p><p><strong>会议时间</strong>： [请填写会议时间]</p><p><strong>会议地点</strong>： [请填写会议地点]</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph 存储系统硬件选型与优化</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph 存储系统介绍</strong></p><ol><li>介绍了 Ceph 存储系统的架构、功能和优势，如高可用性、可扩展性、一致性、去中心化等。</li><li>讨论了 Ceph 对硬件的需求，包括 CPU、内存、存储和网络等方面。</li></ol><p><strong>二、硬件选择常见问题</strong></p><ol><li>指出客户在选择硬件时常见的问题，如未考虑 NVMe 存储、数据副本数过少、使用 SATA 驱动器、未考虑网络带宽等。</li><li>强调了这些问题可能导致数据丢失、性能问题等后果。</li></ol><p><strong>三、硬件选型建议</strong></p><ol><li>节点数量：建议至少 4 个节点，以保证数据冗余和故障域隔离。</li><li>存储类型：建议使用 NVMe 存储，以提高性能和可靠性。</li><li>网络带宽：建议使用 25G 或 100G 以上的网络，以满足性能需求。</li><li>驱动器类型：建议使用 SAS 或 SSD 驱动器，避免使用 SMR 驱动器。</li><li>CPU 和内存：建议根据实际负载进行配置，避免资源瓶颈。</li></ol><p><strong>四、具体配置建议</strong></p><ol><li>节点配置：建议使用 2U 机架式服务器，每个节点配备 2-4 个 NVMe 驱动器，以及足够的 CPU 和内存。</li><li>网络配置：建议使用 25G 或 100G 以上的网络，并配置足够的网络端口。</li><li>存储配置：建议使用 1:2 的 NVMe 与 SAS/SSD 存储比例，以满足性能和容量需求。</li></ol><p><strong>五、案例分析</strong></p><ol><li>分享了某客户使用 90 节点、720 个 OSD 的集群，在 S3 上运行，性能良好的案例。</li><li>分享了某客户使用 50 个 PyTorch 集群，存储了数十亿个文件，并进行了 IO 500 测试，性能稳定的案例。</li></ol><p><strong>六、后续行动计划</strong></p><ol><li>客户根据建议进行硬件升级或优化。</li><li>持续关注 Ceph 社区和上游项目的更新，及时了解新技术和最佳实践。</li><li>为客户提供技术支持和培训。</li></ol><p><strong>七、会议总结</strong></p><p>本次会议重点讨论了 Ceph 存储系统的硬件选型和优化，为参会人员提供了宝贵的经验和建议。希望参会人员能够将所学知识应用到实际工作中，提高 Ceph 存储系统的性能和可靠性。</p><p><strong>改进点</strong>：</p><ol><li>在 &quot;Ceph 存储系统介绍&quot; 中，更详细地介绍了 Ceph 的架构、功能和优势，以及硬件需求。</li><li>在 &quot;硬件选择常见问题&quot; 中，补充了未考虑网络带宽可能导致的问题。</li><li>在 &quot;硬件选型建议&quot; 中，强调了 NVMe 的重要性，并建议使用 SAS 或 SSD 驱动器。</li><li>在 &quot;具体配置建议&quot; 中，提供了更详细的节点配置、网络配置和存储配置建议。</li><li>在 &quot;案例分析&quot; 中，增加了 IO 500 测试的案例。</li><li>在 &quot;后续行动计划&quot; 中，强调了持续关注 Ceph 社区和上游项目的重要性。</li></ol>",22)])])}const C=t(p,[["render",s]]);export{d as __pageData,C as default};
